do $verify$ begin if exists (select 1 from pg_temp.wine_recovery_batch s join public.wine_cost_references t using (wine_id,reference_kind,source_revision) where to_jsonb(t) is distinct from to_jsonb(s)) then raise exception 'Conflicting historical evidence; this import part was not committed'; end if; end $verify$;

select '007-wine-cost-references.sql'::text as completed_part, count(*)::integer as present_records from pg_temp.wine_recovery_batch s join public.wine_cost_references t using (wine_id,reference_kind,source_revision);

commit;

